constraints:
1 <= |str| <= 10^{4}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def removePair(self, S):
		s = []
		for i in S:
			if s and s[-1] == i:
				s.pop()
			else:
				s.append(i)
		if len(s) == 0:
			return -1
		else:
			return ''.join(s)
